// The runtime font store (FB-33 / P2-28): bundled font faces live as
// woff2 files in a fonts/ directory (public/fonts/ in the build — a build
// artifact, regenerated by scripts/gen-font-manifest.cjs, never committed)
// instead of @fontsource CSS imported into the JS/CSS bundle, and load
// on demand through FontFace. The base directory is configurable, so the
// packaging question — stop shipping the files in the package at all and
// fetch them from a userData directory or a server instead — flips with
// one setFontStoreBase() call and no caller changes.
import { FONT_FACES } from './fontManifest.js';

let base = null; // resolved lazily against the page URL
export function setFontStoreBase(url) {
  base = String(url).replace(/\/$/, '') + '/';
}
export function fontStoreBase() {
  if (!base) base = new URL('fonts/', document.baseURI).href;
  return base;
}

const byKey = new Map(FONT_FACES.map((f) => [`${f.family}|${f.weight}|${f.style}`, f]));
export function faceInStore(family, weight, style = 'normal') {
  return byKey.get(`${family}|${weight}|${style}`) || null;
}

const loaded = new Map(); // key -> Promise<boolean> (true = a store face loaded)
export function loadFace(family, weight, style = 'normal') {
  const key = `${family}|${weight}|${style}`;
  if (loaded.has(key)) return loaded.get(key);
  const p = (async () => {
    const face = byKey.get(key);
    if (!face) return false; // not a bundled face (system font or Inter) — nothing to fetch
    try {
      await Promise.all(face.subsets.map(async (s) => {
        const f = new FontFace(family, `url(${fontStoreBase()}${s.file})`, {
          weight: String(weight), style, unicodeRange: s.range,
        });
        await f.load();
        document.fonts.add(f);
      }));
      return true;
    } catch {
      return false;
    }
  })();
  loaded.set(key, p);
  return p;
}
